```python
class Student:
    def __init__(self, name, scores):
        self.name = name
        self.scores = scores

    def average_score(self):
        return sum(self.scores) / len(self.scores)


class Class:
    def __init__(self, students):
        self.students = students

    def calculate_average_scores(self):
        average_scores = []
        for student in self.students:
            average_scores.append(student.average_score())
        return average_scores

    def highest_average_score(self):
        average_scores = self.calculate_average_scores()
        return max(average_scores)

    def lowest_average_score(self):
        average_scores = self.calculate_average_scores()
        return min(average_scores)


# Example usage
