    {"name": "Alice", "scores": [85, 90, 78, 92]},
    {"name": "Bob", "scores": [75, 80, 88, 90]},
    {"name": "Charlie", "scores": [82, 85, 88, 92]}
]

students = [Student(data["name"], data["scores"]) for data in students_data]
class_ = Class(students)

highest_average_score = class_.highest_average_score()
lowest_average_score = class_.lowest_average_score()

print(f"The highest average score is: {highest_average_score}")
print(f"The lowest average score is: {lowest_average_score}")
