def is_prime(n):
    """
    Returns True if the given number is prime, False otherwise.
    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def print_primes_between(a, b):
    """
    Prints all prime numbers between the given two numbers `a` and `b` (where `a` is less than `b`).
    """
    if a >= b:
        raise ValueError("'a' should be less than 'b'")
    for num in range(a, b + 1):
        if is_prime(num):
            print(num)


